let table = {{workflowparams:allData}};

if(table.sales_return_no_type !== -9999 && (
  !table.sales_return_no|| table.sales_return_no === null || table.sales_return_no === ''
)) {
  table.sales_return_no = 'draft'
}

return { table };

let table = {{workflowparams:allData}};

if (
  table.sales_return_no_type !== -9999 &&
  (!table.sales_return_no ||
    table.sales_return_no === null ||
    table.sales_return_no === "" ||
    table.previous_status == "Draft")
) {
  table.sales_return_no = 'issued'
}

return { table };

const entry = {{node:code_node_i1NUMscC.data.table}};

const gdIDs = entry.table_sr.map(item => item.gd_line_id);

return { gdIDs }

const entry = {{node:code_node_i1NUMscC.data.table}};
const gdLineItemList = {{node:search_node_OfTEOTAo.data.data}};

let invalidReturnQty = [];

for (const [index, item] of entry.table_sr.entries()) {
  const gdLine = gdLineItemList.find((gd) => gd.id === item.gd_line_id);
  if (gdLine) {
    const maxReturnableQty = (gdLine.gd_qty || 0) - (gdLine.return_qty || 0);
    if ((item.expected_return_qty || 0) > maxReturnableQty) {
      invalidReturnQty.push(`#${index + 1}`);
    }
  }
}

if(invalidReturnQty.length > 0) {
  return {
    status: 'Failed',
    message: `Line${invalidReturnQty.length > 1 ? "s" : ""} ${invalidReturnQty.join(
        ", ",
      )} ha${
        invalidReturnQty.length > 1 ? "ve" : "s"
      } an expected return quantity exceeding the maximum returnable quantity.`
  }
}

return {
  status: 'Success',
  message: ''
}

let entry = {{node:code_node_i1NUMscC.data.table}};

// Check total return qty
const totalQuantity = entry.table_sr.reduce((sum, item) => {
    const { expected_return_qty } = item;
    return sum + (expected_return_qty || 0);
  }, 0);

if(totalQuantity <= 0){
  return {
    status: 'Failed',
    code: '403',
    message: 'Total return quantity is 0.',
    entry
  }
}

// Check line return qty
let zeroQtyArray = [];
for(const [index, sr] of entry.table_sr.entries()) {
  if (!sr.expected_return_qty || sr.expected_return_qty <= 0) {
    zeroQtyArray.push(`#${index + 1}`);
  }
}

if(zeroQtyArray.length > 0) {
  if(entry.filter_sr == 'Yes') {
    entry.table_sr = entry.table_sr.filter(
      (item) => item.expected_return_qty > 0,
    );

    if(entry.table_sr.length === 0) {
      return {
        status: 'Failed',
        code: '405',
        message: 'All Return Quantity must not be 0. Please add at least one item with return quantity > 0.',
        entry
      }
    }

    let salesOrderNumber = [];
    let soId = [];
    let goodsDeliveryNumber = [];
    let gdId = [];
    for (const sr of entry.table_sr) {
      gdId.push(sr.gd_id);
      goodsDeliveryNumber.push(sr.gd_number);

      soId.push(sr.so_id);
      salesOrderNumber.push(sr.line_so_no);
    }

    soId = [...new Set(soId)];
    gdId = [...new Set(gdId)];
    salesOrderNumber = [...new Set(salesOrderNumber)];
    goodsDeliveryNumber = [...new Set(goodsDeliveryNumber)];

    entry.so_id = soId;
    entry.gd_id = gdId;
    entry.so_no_display = salesOrderNumber.join(", ");
    entry.gd_no_display = goodsDeliveryNumber.join(", ");
  } else {
    return {
      status: 'Failed',
      code: '404',
      message: `Line${zeroQtyArray.length > 1 ? "s" : ""} ${zeroQtyArray.join(", ")} ha${
        zeroQtyArray.length > 1 ? "ve" : "s"
      } a zero return quantity, which may prevent processing.\nIf you proceed, it will delete the row with 0 return quantity. \nWould you like to proceed?`,
      entry
    }
  }
}

return {
  status: 'Success',
  code: '',
  message: '',
  entry
}

let entry = {{workflowparams:allData.sr_status}} === 'Draft' ? {{node:code_node_qFbAnGEH.data.table}} : {{node:code_node_rG74lIOj.data.entry}};
let updatedLineItem = [];

for(const [index, srLineItem] of entry.table_sr.entries()) {
  // Create a new object with formatted values
  const formattedItem = {
    ...srLineItem,
    // Number formatting
    so_quantity: parseFloat(srLineItem.so_quantity?.toFixed(3)) || 0,
    good_delivery_qty: parseFloat(srLineItem.good_delivery_qty?.toFixed(3)) || 0,
    to_returned_qty: parseFloat(srLineItem.to_returned_qty?.toFixed(3)) || 0,
    expected_return_qty: parseFloat(srLineItem.expected_return_qty?.toFixed(3)) || 0,
    received_qty: parseFloat(srLineItem.received_qty?.toFixed(3)) || 0,
    unit_price: parseFloat(srLineItem.unit_price?.toFixed(4)) || 0,
    total_price: parseFloat(srLineItem.total_price?.toFixed(4)) || 0,

    customer_id: entry.customer_id || null,
    plant_id: entry.plant_id || null,
    billing_state_id: entry.billing_address_state || null,
    billing_country_id: entry.billing_address_country || null,
    shipping_state_id: entry.shipping_address_state || null,
    shipping_country_id: entry.shipping_address_country || null,
    line_index: index + 1,
    agent_id: entry.sales_pic_id,
    area_id: entry.sr_area_id,
  };

  updatedLineItem.push(formattedItem);
}

entry.table_sr = updatedLineItem;

return { entry }

const gdLineItemList = {{node:search_node_OfTEOTAo.data.data}};
const srData = {{node:code_node_qYJ8wTWS.data.srData}};
let latestGDLineItemList = [];

for(const gdLineItem of gdLineItemList) {
  const returnQty = srData.table_sr.find(item => item.gd_line_id === gdLineItem.id)?.expected_return_qty ?? 0;

  const latestReturnQty = parseFloat(returnQty) + parseFloat(gdLineItem.return_qty || 0);

  latestGDLineItemList.push({
    id: gdLineItem.id,
    return_qty: latestReturnQty.toFixed(3),
    sr_status: parseFloat(latestReturnQty) >= parseFloat(gdLineItem.gd_qty || 0) ? "Fully Returned" : "Partially Returned",
  })
}

return { latestGDLineItemList }

const gdList = {{node:search_node_gnlJ7vR5.data.data}};

const latestGDList = gdList.map((item, index) => {
  const updatedGDStatus = item.table_gd.some(
    (gdItem) =>
      parseFloat(gdItem.return_qty || 0) < parseFloat(gdItem.gd_qty || 0),
  )
    ? "Partially Returned"
    : "Fully Returned";

  return {
    id: item.id,
    sr_status: updatedGDStatus,
  };
});

return { latestGDList }

const srSetup = {{node:get_node_rx6bgxbr.data.data}} ?? null;

if(!srSetup || !srSetup.id || srSetup.id === '') {
  return {
    createCN: 'No'
  }
} else {
  return {
    createCN: srSetup.auto_cn != 1 || srSetup.trigger_by != 'Sales Return' ? 'No' : 'Yes'
  }
}

const siList = {{node:search_node_3wVLWJqB.data.data}};
const siLineItemList = {{node:search_node_U59iQSEF.data.data}};
const srData = {{node:code_node_qYJ8wTWS.data.srData}};

// Condition 1: one gd_line_id must map to exactly one SI
const gdLineToSIMap = {};
for (const siLine of siLineItemList) {
  if (!siLine.gd_line_id) continue;
  if (gdLineToSIMap[siLine.gd_line_id]) {
    return {
      status: 'Failed',
      message: `GD is mapped to more than one SI.`
    };
  }
  gdLineToSIMap[siLine.gd_line_id] = siLine.si_id;
}

// Condition 2: one SI must map to exactly one gd_id in srData
const multipleGDSI = siList.filter(si => si.gd_id.length > 1)
if(multipleGDSI.length > 0) {
  return {
    status: 'Failed',
    message: `SI contains more than one GDs.`
  };
}

// Condition 3 & 4: check per SR line
for (const [index, sr] of srData.table_sr.entries()) {
  const matchedSILine = siLineItemList.find(line => line.gd_line_id === sr.gd_line_id);
  if (!matchedSILine) {
    return {
      status: 'Failed',
      message: `No matching SI line found for GD Line ID ${sr.gd_line_id}.`
    };
  }

  // Condition 3: invoice_qty must be greater than return qty
  const returnQty = parseFloat(sr?.expected_return_qty) ?? 0;
  if (parseFloat(matchedSILine.invoice_qty) - parseFloat(matchedSILine.credit_qty) < returnQty) {
    return {
      status: 'Failed',
      message: `Invoice quantity (${matchedSILine.invoice_qty}) must be greater than return quantity (${returnQty}).`
    };
  }

  // Condition 4: si_amount must be greater than 0
  if (matchedSILine.si_amount <= 0) {
    return {
      status: 'Failed',
      message: `Invoice line total must be greater than 0.`
    };
  }
}

return {
  status: 'Passed',
  message: ''
};

const formatNumberTo4 = (value) => {
  if (value === null || value === undefined || value === "") return "0.0000";
  return parseFloat(value).toFixed(4);
};

const formatNumberTo3 = (value) => {
  if (value === null || value === undefined || value === "") return "0.000";
  return parseFloat(value).toFixed(3);
};

const roundTo4 = (value) => {
  return Math.round((parseFloat(value) || 0) * 10000) / 10000;
};

const calculateFinalPrice = (total, invoiceQty, creditQty) => {
  const priceForCredit =
    (roundTo4(total) / roundTo4(invoiceQty)) * roundTo4(creditQty);

  return roundTo4(priceForCredit);
};

const sumPrice = (fieldName, cnLineItemList) => {
  return roundTo4(
    cnLineItemList.reduce((total, item) => {
      return roundTo4(total) + roundTo4(item[fieldName]);
    }, 0),
  );
};

const srData = {{node:code_node_qYJ8wTWS.data.srData}};
const siLineItemList = {{node:search_node_U59iQSEF.data.data}};
const siList = {{node:search_node_3wVLWJqB.data.data}};
const cnDocFormat = {{node:get_node_YkDvO5xI.data.data}};
const customerData = {{node:get_node_vcDlmNfk.data.data}};
const currencyCode = {{node:get_node_0U04xCWm.data.data}};
const shippingAddress = {{node:get_node_vEuXoaDu.data.data}};
const billingAddress = {{node:get_node_Htx4STEq.data.data}};
let cnLineItemList = [];

for (const [index, srLineItem] of srData.table_sr.entries()) {
  const matchedSILineItem = siLineItemList.find(
    (item) => item.gd_line_id === srLineItem.gd_line_id,
  );

  const matchedSI = siList.find(
    (item) => item.id === matchedSILineItem.sales_invoice_id,
  );

  const cnLineItem = {
    si_id: matchedSILineItem?.sales_invoice_id || "",
    item_id: srLineItem.material_id,
    item_name: srLineItem.material_name,
    uom_id: srLineItem.quantity_uom,
    credit_qty: formatNumberTo3(srLineItem.expected_return_qty),
    unit_price: formatNumberTo4(matchedSILineItem.unit_price),
    subtotal:
      roundTo4(srLineItem.expected_return_qty) *
      roundTo4(matchedSILineItem.unit_price),
    discount: roundTo4(matchedSILineItem.si_discount),
    discount_type: matchedSILineItem?.si_discount_uom_id || "",
    discount_amount: calculateFinalPrice(
      matchedSILineItem.discount_amount,
      matchedSILineItem.invoice_qty,
      srLineItem.expected_return_qty,
    ),
    tax_code: matchedSILineItem?.si_tax_rate_id || "",
    tax_percent: matchedSILineItem?.tax_percent || "",
    tax_amount: calculateFinalPrice(
      matchedSILineItem.tax_amount,
      matchedSILineItem.invoice_qty,
      srLineItem.expected_return_qty,
    ),
    total: calculateFinalPrice(
      matchedSILineItem.si_amount,
      matchedSILineItem.invoice_qty,
      srLineItem.expected_return_qty,
    ),
    line_status: "Closed",
    line_index: index + 1,
    si_line_id: matchedSILineItem?.id || "",
    sr_line_id: srLineItem.id,
    sr_id: srData.sales_return_id,
    plant_id: srData.plant_id,
    customer_id: srData.customer_id,
    tax_inclusive: matchedSILineItem?.si_tax_inclusive || 0,
    invoice_qty: formatNumberTo3(matchedSILineItem.invoice_qty),
    item_desc: srLineItem.material_desc,
    si_no: matchedSI?.sales_invoice_no || "",
    more_desc: srLineItem.more_desc,
    available_credit_qty: formatNumberTo3(
      matchedSILineItem.invoice_qty - matchedSILineItem.credit_qty,
    ),
  };

  cnLineItemList.push(cnLineItem);
}

const cnData = {
  cn_status: "Completed",
  page_status: "Add",
  acc_integration_type: srData.acc_integration_type,
  organization_id: srData.organization_id,
  previous_status: null,
  plant_id: srData.plant_id,
  customer_id: srData.customer_id,
  currency_code: currencyCode?.currency_code || "",
  cn_no: "issued",
  cn_no_type: cnDocFormat.id,
  cn_date: new Date().toISOString().split("T")[0],
  cn_type: "Return",
  source_type: "Sales Invoice",
  source_id: [...new Set(cnLineItemList.map((item) => item.si_id))],
  source_no: [...new Set(cnLineItemList.map((item) => item.si_no))].join(", "),
  sales_return_id: srData.id,
  total_gross_currency: currencyCode?.currency_code || "",
  total_discount_currency: currencyCode?.currency_code || "",
  total_tax_currency: currencyCode?.currency_code || "",
  total_amount_currency: currencyCode?.currency_code || "",
  total_amount_myr: "MYR",
  subtotal: sumPrice("subtotal", cnLineItemList),
  total_discount: sumPrice("discount_amount", cnLineItemList),
  tax_total: sumPrice("tax_amount", cnLineItemList),
  grand_total: sumPrice("total", cnLineItemList),
  myr_grand_total:
    sumPrice("total", cnLineItemList) *
    roundTo4(currencyCode.currency_buying_rate),
  table_cn: cnLineItemList,
  remark: srData.remark,
  billing_address_name: billingAddress.address_name ?? null,
  billing_address_phone: billingAddress.address_phone ?? null,
  billing_address_line_1: billingAddress.address_line_1 ?? null,
  billing_address_line_2: billingAddress.address_line_2 ?? null,
  billing_address_line_3: billingAddress.address_line_3 ?? null,
  billing_address_line_4: billingAddress.address_line_4 ?? null,
  billing_address_city: billingAddress.address_city ?? null,
  billing_postal_code: billingAddress.address_postal_code ?? null,
  billing_address_state: billingAddress.adddress_state ?? null,
  billing_address_country: billingAddress.address_country_id ?? null,
  billing_attention: billingAddress.address_attention ?? null,
  shipping_address_name: shippingAddress.address_name ?? null,
  shipping_address_phone: shippingAddress.address_phone ?? null,
  shipping_address_line_1: shippingAddress.address_line_1 ?? null,
  shipping_address_line_2: shippingAddress.address_line_2 ?? null,
  shipping_address_line_3: shippingAddress.address_line_3 ?? null,
  shipping_address_line_4: shippingAddress.address_line_4 ?? null,
  shipping_address_city: shippingAddress.address_city ?? null,
  shipping_postal_code: shippingAddress.address_postal_code ?? null,
  shipping_address_country: shippingAddress.address_country_id ?? null,
  shipping_address_state: shippingAddress.adddress_state ?? null,
  shipping_attention: shippingAddress.address_attention ?? null,
  exchange_rate_myr: "MYR",
  exchange_rate_currency: currencyCode?.currency_code || "",
  exchange_rate: currencyCode?.currency_buying_rate || "1.0000",
  cn_billing_address: billingAddress.address ?? null,
  cn_shipping_address: shippingAddress.address ?? null,
  posted_status: "Unposted",
};

return { cnData };
